@font-face { font-family: "Reader Pixel"; src: url("data:font/woff2;base64,") format("woff2"); font-style: normal; font-weight: 400; font-display: block; }
:root {
  --reader-text-color: #303b32;
  --reader-page-background: #eae2c7;
  --reader-accent: #376b42;
  --reader-font-family: "Noto Sans CJK SC", "Noto Sans SC", "Source Han Sans SC", "Microsoft YaHei", sans-serif;
  --reader-font-size: 18px;
  --reader-line-height: 1.8;
  --reader-paragraph-indent: 2em;
  --reader-paragraph-spacing: .72em;
  --mc-pixel: "Reader Pixel", monospace;
  --mc-stone: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAD1BMVEV5eXlkZGRRUVE9PUMvLzfdbkGmAAAAZUlEQVR42hXJQRHEMAwDQIVBLAS1FQA3VhA04Y/ppvtdjCoHVdC1syzE4LpnG005EcQpd8wQkPVGVmJwuXwbtGfoFCQ/pBu+ldX7gGztU0BoQuoB+gm6A95v6Fx/t3/MCZDriYo/+sYRXDxJGR4AAAAASUVORK5CYII=");
  --mc-ore: url("data:image/png;base64,");
  --mc-paper: url("data:image/png;base64,");
}
body { margin: 0; color: var(--reader-text-color); background: var(--reader-page-background); font: 400 var(--reader-font-size)/var(--reader-line-height) var(--reader-font-family); letter-spacing: normal; font-style: normal; }
.mc-page { position: relative; isolation: isolate; display: grid; grid-template-rows: 134px minmax(0, 1fr) 64px; gap: 12px; box-sizing: border-box; width: 100%; height: 100%; min-width: 0; overflow: hidden; padding: 0 19px 12px; background: #516346; }
.mc-page { image-rendering: pixelated; }
.mc-page::after { content: ""; position: absolute; inset: 0; border: 4px solid #132d294d; box-shadow: inset 0 0 0 1px #ffffff21; pointer-events: none; z-index: 5; }
.mc-overworld { background: linear-gradient(#6e885234, #30493699), url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAFVBMVEXCnWK4lF+vj1WfhE2WdEF+YjdnUCyo+21oAAAAcElEQVR42g3CARXDIAwFwM/DAAk1kGQCVoKDDQeAA+JfQnvvwAV4XyD9CSk5hMS8yYUxR6wTG+WLjKQ3hFtvQgwX/RCbI9aIWHOjJMWrgonMzTqSuqt6RcwRZ+xALqkiJ0DJ7WZWWONO5o6zz3+ciAdixhUFVj2uwQAAAABJRU5ErkJggg==") 0 0/64px 64px; }
.mc-world-edge { position: absolute; inset: 121px 0 0; background: url("data:image/png;base64,") 0 0/48px 48px repeat-x; opacity: .85; pointer-events: none; }
.mc-sky { position: relative; margin: 0 -19px; min-width: 0; overflow: hidden; background: linear-gradient(#76b9d1, #b9e8e6 74%, #8dc7b4); border-bottom: 4px solid #496531; }
.mc-sky::after { content: ""; position: absolute; inset: auto 0 0; height: 12px; background: url("data:image/png;base64,") 0 0/40px 40px; image-rendering: pixelated; }
.mc-world-name { position: absolute; z-index: 2; top: 15px; left: 20px; display: flex; flex-direction: column; align-items: flex-start; color: #203b37; }
.mc-edition { font: 6px/1.8 var(--mc-pixel); color: #385950; letter-spacing: .1px; }
.mc-world-name strong { margin-top: 7px; font: 21px/1.3 var(--mc-pixel); letter-spacing: -1px; color: #f8f0d8; text-shadow: -2px -2px #314540, 2px -2px #314540, -2px 2px #314540, 2px 2px #314540, 0 4px #314540, 2px 5px #ffffff48; }
.mc-world-caption { margin-top: 8px; font: 600 10px/1.5 var(--reader-font-family); letter-spacing: 3px; }
.mc-sun { position: absolute; width: 22px; height: 22px; top: 13px; right: 32px; background: #fff7c6; box-shadow: 0 0 0 5px #fff7c647, 0 0 0 11px #fff7c623; }
.mc-cloud { position: absolute; height: 8px; width: 56px; background: #f4faf0c9; box-shadow: 15px -6px #f4faf0c9, 27px 6px #f4faf06b; pointer-events: none; }
.mc-cloud-one { top: 31px; right: 116px; }
.mc-cloud-two { top: 65px; right: -12px; transform: scale(.7); opacity: .75; }
.mc-landscape { position: absolute; z-index: 1; width: 234px; height: 138px; right: -13px; bottom: -3px; pointer-events: none; }
.mc-landscape svg { display: block; width: 100%; height: 100%; image-rendering: pixelated; }
.mc-book-sign { position: absolute; z-index: 3; left: 19px; bottom: 11px; display: flex; align-items: center; gap: 6px; width: 53%; min-width: 0; box-sizing: border-box; padding: 4px 7px; background: #304c3bf2; border: 1px solid #c7e2a862; box-shadow: 2px 2px #294129; color: #f2edcb; }
.mc-book-sign [data-reader-field] { font: 11px/1.5 var(--reader-font-family); white-space: nowrap; text-overflow: ellipsis; overflow: hidden; }
.mc-biome { position: absolute; right: 15px; bottom: 5px; z-index: 3; font: 5px/1.5 var(--mc-pixel); color: #eff1d5; text-shadow: 1px 1px #263d25; }
.mc-paper { position: relative; z-index: 2; display: grid; grid-template-rows: minmax(0, 1fr); min-width: 0; min-height: 0; padding: 21px 16px 10px 12px; box-sizing: border-box; background: #efe8d2; border: 2px solid #beaf88; box-shadow: 0 0 0 2px #273f2dbb, 3px 5px #1c342960, inset 0 0 0 2px #f5ecd2; }
.mc-paper::before { content: ""; position: absolute; inset: -2px; background: var(--mc-paper) center/100% 100%; image-rendering: pixelated; opacity: .12; pointer-events: none; }
.mc-paper-corner { position: absolute; z-index: 2; width: 10px; height: 10px; border-color: #6f8753; border-style: solid; pointer-events: none; }
.mc-paper-nw { top: 4px; left: 4px; border-width: 3px 0 0 3px; }
.mc-paper-se { bottom: 4px; right: 4px; border-width: 0 3px 3px 0; }
.mc-paper-tab { position: absolute; z-index: 2; top: -9px; right: 14px; display: flex; align-items: center; gap: 4px; height: 18px; padding: 0 6px; background: #365440; border: 1px solid #b4c090; box-shadow: 2px 2px #22382d; color: #e2e4be; font: 9px/1.4 var(--reader-font-family); letter-spacing: 1px; pointer-events: none; }
.mc-body { position: relative; z-index: 1; min-width: 0; min-height: 0; text-align: justify; text-spacing-trim: space-all; image-rendering: auto; --legado-highlight-room-left: 12px; --legado-highlight-room-right: 12px; }
.mc-body .reader-template-flow-content { box-sizing: border-box; padding-left: 12px; }
.reader-paragraph { position: relative; display: block; margin: 0 0 var(--reader-paragraph-spacing); text-indent: var(--reader-paragraph-indent); break-inside: auto; page-break-inside: auto; orphans: 1; widows: 1; }
.reader-paragraph[data-mc-ordinal]::before { content: attr(data-mc-ordinal); position: absolute; top: .95em; left: -13px; width: 10px; text-align: left; text-indent: 0; color: #899171; font: 5px/1 var(--mc-pixel); pointer-events: none; }
.reader-paragraph.mc-lead { text-indent: 0; }
/* A first-letter box changes joined-emoji selection in Chromium. Keep source runs intact. */
.mc-lead:not([data-reader-continuation]):not([data-split-from])::first-line { font-weight: 600; color: #3d683d; }
.reader-paragraph.mc-dialogue { text-indent: 0; padding-left: .55em; border-left: 2px solid #829369; color: #455945; background: linear-gradient(90deg, #718d5420, transparent 76%); box-decoration-break: slice; -webkit-box-decoration-break: slice; }
.reader-paragraph.mc-scene { text-align: center; text-indent: 0; letter-spacing: .3em; color: #789273; }
.reader-paragraph.mc-scene::before, .reader-paragraph.mc-scene::after { content: ""; position: absolute; top: 50%; height: 2px; width: 21%; background: repeating-linear-gradient(90deg, #879a6b 0 5px, transparent 5px 8px); pointer-events: none; }
.reader-paragraph.mc-scene::before { left: 7%; }
.reader-paragraph.mc-scene::after { right: 7%; }
[data-reader-continuation], .reader-paragraph[data-split-from] { text-indent: 0; }
.reader-paragraph[data-reader-continuation]::before, .reader-paragraph[data-split-from]::before { display: none; }
.reader-chapter-title { position: relative; display: block; font: 650 1.38em/1.45 var(--reader-font-family); color: #304e39; text-indent: 0; text-align: left; letter-spacing: .025em; overflow-wrap: anywhere; margin: .12em 0 .75em; padding: .1em 0 .58em; border-bottom: 2px solid #84946775; break-before: auto; break-after: auto; break-inside: auto; page-break-before: auto; page-break-after: auto; page-break-inside: auto; orphans: 1; widows: 1; }
.reader-chapter-title::before { content: "CHAPTER " attr(data-mc-chapter); display: block; margin-bottom: .8em; color: #68845a; font: 7px/1.6 var(--mc-pixel); letter-spacing: 0; }
.reader-chapter-title::after { content: ""; position: absolute; width: 13px; height: 13px; right: 0; bottom: -7px; background: #efe8d2 url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAIVBMVEUAAADb/+uv/c2C9q1B84QX3WIAqiwAlSkAexgAUwAALQC5+lfcAAAAAXRSTlMAQObYZgAAAENJREFUeNpjwApmzoTQnCKuE8CMiSpuUWABIRW31AUghmqQWhmUYdaGxgg2a4UyPEpBDIZpFe1WEAPTgTJgsGoVVpsBDRwS6h42ddsAAAAASUVORK5CYII=") center/13px 13px no-repeat; image-rendering: pixelated; box-shadow: -5px 0 #efe8d2; }
.reader-chapter-title[data-split-from] { margin-top: 0; padding-top: 0; }
.reader-chapter-title[data-split-from]::before, .reader-chapter-title[data-split-to]::after { display: none; }
figure { margin: 0 0 var(--reader-paragraph-spacing); text-align: center; }
img, svg, video, canvas { max-width: 100%; max-height: 100%; object-fit: contain; }
.mc-item { display: inline-block; flex: none; width: 16px; height: 16px; background-position: center; background-size: contain; background-repeat: no-repeat; image-rendering: pixelated; pointer-events: none; }
.mc-item-book { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAIVBMVEUAAADW1ta3t7eZmZlbW1tlSxdUPhNSLhBEJQoxIQQWEAXuGgy6AAAAAXRSTlMAQObYZgAAAFhJREFUeNpjQAEzJ0Dp0kwoHRo6AUK3hkYC6bLQ0IjQsAkM01MjQoFCnRCZ0A4HhpnqoUDayIBhuVAZkFaewcBVqA6iVzEAhSA0UEi5A0QDhSA0UGgVigsAYf4glv1MND8AAAAASUVORK5CYII="); }
.mc-item-pickaxe { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAHlBMVEUAAAAz68srx6wnspqJZydoTh5JNhUOPzYoHgsIJSBDqdTeAAAAAXRSTlMAQObYZgAAAEZJREFUeNpjwArKywvANLuQsXoqmFU509iDAQKSLCE0W4TRBDAjpWHyBIgAw+QJEAGGSRMgAgwTJ0AEGDihAlAtUEYHms0AO88PQ5cytswAAAAASUVORK5CYII="); }
.mc-item-map { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAeElEQVQ4y2NgGBJg+QqP/yBMtuZXr47/v3V3FWmGwGwFafzz5xMYgwwiyhCYrTCNyBhkYHuH5X+ibcWGQWowDIFpxGUzuitQDCFFMywsMFwAEiBkCCw2cIYBPkNgtuLUjMsQEL37YDlhjdgMgWkkSTOyIWRppDsAABifRorVNHrHAAAAAElFTkSuQmCC"); }
.mc-item-compass { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAoklEQVQ4y82Tyw2AIBBEKUKjXXCiDGMHnKiEaqjCOuhmzZAMQVw/RzaZoMvMCwIaM2Q550TT72BKqSjGKN77Or6C1mWpZpistRehh3kIXjWsBZ9AFwhensIhBBXyC7Bvm8g0lfETgE3TIAD0YezTDYAmqw0c81yf4YGwIhWQcy5iYVXs8SgRvgHaz2CAId4JHqEabiEtqAdw/vNG0thrzB/vBGBOD7CWHulfAAAAAElFTkSuQmCC"); }
.mc-item-diamond { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAIVBMVEUAAAD////V//ah++hK7dks4NggxbUaqqcckZoRcnoUXlN/hNeyAAAAAXRSTlMAQObYZgAAAF1JREFUeNpjwApmzoTQnIJCE8CMiS5GWWABEWNltwVghpCQC4gx0dHFuKwKxHByNm4DM8SMTdpBjEku5eVpXUAGl3taWtkCECM8La0YxGBY4WKcBTaZa9WqBUg2AwByXRcdUQ3W3QAAAABJRU5ErkJggg=="); }
.mc-item-apple { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAIVBMVEUAAAD/lp3/Xmn/HCvdFyV+Nw60Ex51KAKcEBdUJAlUCQ5dkieqAAAAAXRSTlMAQObYZgAAAFxJREFUeNpjQAHsMEYkjFEAoTjapxeA6cTMlnQQq81IUMisHMQwNjZ2TgcxnJ1dnL2AjLIUt5RkMCMtzS05C2Rsmlua2wIQoy3NJQPEYFiR0dbFAAJc5VULkFwAACePFkH36dcVAAAAAElFTkSuQmCC"); }
.mc-item-emerald { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAIVBMVEUAAADb/+uv/c2C9q1B84QX3WIAqiwAlSkAexgAUwAALQC5+lfcAAAAAXRSTlMAQObYZgAAAENJREFUeNpjwApmzoTQnCKuE8CMiSpuUWABIRW31AUghmqQWhmUYdaGxgg2a4UyPEpBDIZpFe1WEAPTgTJgsGoVVpsBDRwS6h42ddsAAAAASUVORK5CYII="); }
.mc-item-pearl { background-image: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAIVBMVEUAAACM9OIszbE0mYglhHQbe2sQXlELTUIMNzAGOTEDJiC5a2thAAAAAXRSTlMAQObYZgAAAFtJREFUeNpjwAo4OqB0swmE1WyS5rIAJGAiVJ7mBWIYas4szwLJOM1aNb0MKLc4HchwAzKWgBhmQAaXe+XMIisGIMOtvFwRpJhhabozUAYktCxtFZACsVYh2wwA2BYa2KT1S0MAAAAASUVORK5CYII="); }
.mc-item-enchanted { background-image: url("data:image/png;base64,"); }
.mc-item-clock { background-image: url("data:image/png;base64,"); }
.mc-footer { position: relative; z-index: 2; min-width: 0; color: #f0eaca; }
.mc-status { display: flex; align-items: center; justify-content: space-between; gap: 8px; height: 17px; font: 9px/1.4 var(--mc-pixel); text-shadow: 1px 1px #18352c; }
.mc-time { display: flex; align-items: center; gap: 5px; min-width: 0; }
.mc-status [data-reader-field] { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mc-folio { display: flex; align-items: center; gap: 6px; color: #c5ed86; min-width: 0; }
.mc-folio > span { font-size: 5px; color: #d1dcb4; }
.mc-folio b { font-weight: 400; }
.mc-completion { font-size: 7px; }
.mc-xp { position: relative; height: 5px; margin: 4px 0 5px; background: #102b23; border: 1px solid #081b12; box-shadow: 0 1px #ffffff25; overflow: hidden; }
.mc-xp::after { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 20px, #123a2760 20px 22px); }
.mc-xp i { display: block; width: 100%; height: 100%; background: linear-gradient(#c1ee6f 0 35%, #78be39 35% 75%, #447d27 75%); transform: scaleX(0); transform-origin: left; }
.mc-inventory { position: relative; display: flex; align-items: center; justify-content: center; gap: 8px; height: 29px; }
.mc-hotbar { position: relative; display: flex; align-items: center; justify-content: space-around; width: 236.6px; height: 28.6px; padding: 0 1.3px; box-sizing: border-box; background: url("data:image/png;base64,") center/100% 100%; image-rendering: pixelated; }
.mc-hotbar .mc-item { width: 21px; height: 21px; }
.mc-hotbar-active { position: absolute; left: -1.3px; top: -1.3px; width: 31.2px; height: 31.2px; background: url("data:image/png;base64,") center/100% 100%; image-rendering: pixelated; }
.mc-hearts { display: flex; flex-direction: column; gap: 1px; }
.mc-hearts i { display: block; width: 9px; height: 9px; background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAkAAAAJCAYAAADgkQYQAAAAOUlEQVR4XmNgIAX8Fxb+D8LobFQFJ06AJdAxqiIcGK5oNxZJEAaJwxVhU4ihAAZgCnEqgAGCCnABALrRSFdXao4/AAAAAElFTkSuQmCC") center/contain no-repeat; image-rendering: pixelated; }
.mc-inventory-mark { font: 5px/1 var(--mc-pixel); color: #abda70; }
.mc-cave { grid-template-rows: 53px minmax(0, 1fr) 64px; padding-top: 15px; background: radial-gradient(ellipse at 8% 29%, #41c6c13b, transparent 45%), radial-gradient(ellipse at 98% 85%, #36aeb62b, transparent 40%), linear-gradient(#151c2480, #141e2499), var(--mc-stone) 0 0/64px 64px; }
.mc-cave::after { border-color: #101d21b0; }
.mc-underground { position: relative; z-index: 2; display: flex; align-items: center; gap: 10px; min-width: 0; color: #dbe7d5; }
.mc-tool-slot { flex: none; display: flex; align-items: center; justify-content: center; box-sizing: border-box; width: 43px; height: 43px; background: #263e40; border: 2px solid #102325; box-shadow: inset 2px 2px #71918a, inset -2px -2px #18282c, 2px 2px #0e1d22; }
.mc-tool-slot .mc-item { width: 32px; height: 32px; }
.mc-cave-heading { display: flex; flex-direction: column; gap: 7px; min-width: 0; flex: 1; }
.mc-depth { font: 6px/1.5 var(--mc-pixel); color: #7dcac2; }
.mc-running-title { font: 12px/1.5 var(--reader-font-family); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mc-coordinate { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; font: 7px/1.5 var(--mc-pixel); color: #72b4ab; }
.mc-coordinate span { font-size: 5px; }
.mc-coordinate b { font-weight: 400; color: #d6eaca; }
.mc-cave .mc-paper { background-color: #eee5cc; border-color: #94ac95; box-shadow: 0 0 0 2px #0d2b2d, 3px 5px #071417a6, inset 0 0 0 2px #f8edd0; }
.mc-cave .mc-paper-tab { background: #244c4b; border-color: #7ca89a; color: #d0e7cc; }
.mc-cave .mc-paper-corner { border-color: #4e8d80; }
.mc-rockwork { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.mc-rockwork i { position: absolute; width: 48px; height: 48px; background: var(--mc-ore) center/48px 48px; image-rendering: pixelated; box-shadow: inset 3px 3px #77959133, inset -3px -3px #101a23bb; }
.mc-rockwork i:nth-child(1) { top: 78px; left: -17px; }
.mc-rockwork i:nth-child(2) { top: 43%; right: -22px; }
.mc-rockwork i:nth-child(3) { bottom: 73px; left: -22px; }
