/* The page paints behind every system inset. Only its content is inset. */
:root { --mc-sky-top: #569bbd; --mc-sky-bottom: #bee5d6; --mc-star-opacity: 0; --mc-celestial-x: 54%; --mc-celestial-y: 12%; }
