.mc-cave { --mc-header: 53px; --mc-top: 15px; padding-top: calc(var(--mc-top) + var(--reader-safe-top, 0px)); grid-template-rows: var(--mc-header) minmax(0, 1fr) var(--mc-footer); }
.mc-page::after { border-width: 3px; }
.mc-sky { margin-left: calc(0px - var(--mc-side) - var(--reader-safe-left, 0px)); margin-right: calc(0px - var(--mc-side) - var(--reader-safe-right, 0px)); background: linear-gradient(var(--mc-sky-top), var(--mc-sky-bottom)); }
